head.script:
scwin.screenId = "jldinf00110";

///////// 1. 변수 및 선언 영역 /////////

scwin.delay = false;

scwin.result = undefined;


///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf00110.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_chgPw_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_chgPw_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_chgPw_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.chgPw()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00110.btn_chgPw_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_delayPwChgEndDd_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_delayPwChgEndDd_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_delayPwChgEndDd_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.delayPwChgEndDd()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf00110.btn_delayPwChgEndDd_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_chgPw
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_chgPw = async function () {
    const sbmOptions = {
        id: "tx_fn_chgPw",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_chgPwReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf00110.tx_fn_chgPw" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_delayPwChgEndDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_delayPwChgEndDd = async function () {
    const sbmOptions = {
        id: "tx_fn_delayPwChgEndDd",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_delayPwChgEndDdReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf00110.tx_fn_delayPwChgEndDd" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.chgPw
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chgPw = function () {
    /* sdd-asis-lifecycle:begin fn_chgPw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    document.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldbnf00001/jldbnf00001.xml');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delayPwChgEndDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delayPwChgEndDd = async function () {
    /* sdd-asis-lifecycle:begin fn_delayPwChgEndDd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent("dma_chgPwReq").set("method", "delayPwChgEndDd");
    fm.action = "/account/userPw.do";
    fm.target = "_self";
    await scwin.tx_fn_delayPwChgEndDd();
    /* sdd-asis-lifecycle:end */
};
